# hypothesis: A metaclass __call__ annotated -> object makes Point(3) evaluate to object, so passing Point as Callable[[int], T] infers T as object in mypy and ty alike.
from collections.abc import Callable
from typing import reveal_type


class Wrapping(type):
    def __call__(cls, *args: int) -> object:
        return super().__call__(*args)


class Point(metaclass=Wrapping):
    def __init__(self, x: int) -> None:
        self.x = x


def make[T](factory: Callable[[int], T], n: int) -> T:
    return factory(n)


direct = Point(3)
reveal_type(direct)
via_factory = make(Point, 4)
reveal_type(via_factory)
print(type(direct).__name__, type(via_factory).__name__)
